const scores = [
  { player: "Wanjiru", level: 3, points: 420 },
  { player: "Otieno", level: 5, points: 980 },
  { player: "Amina", level: 5, points: 980 },
  { player: "Juma", level: 1, points: 90 },
];

const total = scores.reduce((sum, s) => sum + s.points, 0);
const perLevel = scores.reduce((t, s) => {
  t[s.level] = (t[s.level] || 0) + s.points;
  return t;
}, {});

const leaderboard = [...scores]                    // copy: sort changes the array
  .sort((a, b) => b.points - a.points || a.player.localeCompare(b.player))
  .map((s, i) => `${i + 1}. ${s.player} ${s.points}`);

const juma = scores.find((s) => s.player === "Juma");
console.log(total, perLevel, leaderboard, juma.level, scores.some((s) => s.points > 900));

