exercises.solution:
function totalsPerCrop(harvests) {
  return harvests.reduce((totals, h) => {
    totals[h.crop] = (totals[h.crop] || 0) + h.kg;
    return totals;
  }, {});
}

function grandTotal(harvests) {
  return harvests.reduce((sum, h) => sum + h.kg, 0);
}

function cropsOver(harvests, kg) {
  return Object.entries(totalsPerCrop(harvests))
    .filter(([, total]) => total > kg)
    .map(([crop]) => crop)
    .sort((a, b) => a.localeCompare(b));
}

