function sortByKg(harvests) {
  // copy first: sort() reorders the array it is called on
  return [...harvests].sort((a, b) => b.kg - a.kg || a.farmer.localeCompare(b.farmer));
}

function findFarmer(harvests, name) {
  const want = name.trim().toLowerCase();
  return harvests.find((h) => h.farmer.toLowerCase() === want) || null;
}

