exercises.solution:
function totalBy(harvests, key) {
  return harvests.reduce((t, h) => {
    t[h[key]] = (t[h[key]] || 0) + h.kg;
    return t;
  }, {});
}

function report(harvests, prices) {
  return Object.entries(totalBy(harvests, "crop"))
    .map(([crop, kg]) => ({ crop, kg, ksh: kg * (prices[crop] || 0) }))
    .sort((a, b) => b.ksh - a.ksh || a.crop.localeCompare(b.crop));
}

function topFarmers(harvests, n) {
  return Object.entries(totalBy(harvests, "farmer"))
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, n)
    .map(([name]) => name);
}
